# Tests for /bin/make inside UC.OS. Each case is a directory of files, a
# command script and the output GNU Make gave for it on a build machine
# (generated by bin/make/tests/os/gen.mjs).
# Run:  sh /usr/share/tests/make/run.sh [case ...]
D=/usr/share/tests/make
T=/tmp/make-tests.$$
mkdir -p $T
pass=0
fail=0
list="$*"
if [ -z "$list" ]; then list=$(cat $D/cases.list); fi
for name in $list; do
  cp -r $D/cases/$name $T/$name
  cd $T/$name
  sh $D/cmd/$name > $T/$name.out 2>&1
  cd /
  got=$(cat $T/$name.out)
  want=$(cat $D/expected/$name)
  if [ "$got" = "$want" ]; then
    pass=$((pass + 1))
    echo "ok    $name"
  else
    fail=$((fail + 1))
    echo "FAIL  $name"
    echo "----- expected"
    cat $D/expected/$name
    echo "----- got"
    cat $T/$name.out
    echo "-----"
  fi
done
echo "make-tests: $((pass + fail)) checks, $pass passed, $fail failed"
